<?php require_once 'layout.php'; require_auth(); if(is_admin()) redirect(BASE_URL.'/admin.php');
if(isset($_GET['currency']) && in_array($_GET['currency'],['TRY','USD','EUR'])) $_SESSION['currency']=$_GET['currency'];
if(isset($_GET['remove'])){db()->prepare('DELETE FROM cart WHERE user_id=? AND product_id=?')->execute([$_SESSION['user_id'],(int)$_GET['remove']]);flash(t('Sepetten çıkarıldı.','Removed from cart.'));redirect(BASE_URL.'/cart.php');}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['qty'])){foreach($_POST['qty'] as $pid=>$q){$pid=(int)$pid;$q=max(1,(int)$q);$st=db()->prepare('SELECT stock FROM products WHERE id=?');$st->execute([$pid]);$stock=(int)$st->fetchColumn();$q=min($q,$stock);db()->prepare('UPDATE cart SET quantity=? WHERE user_id=? AND product_id=?')->execute([$q,$_SESSION['user_id'],$pid]);}flash(t('Sepet güncellendi.','Cart updated.'));redirect(BASE_URL.'/cart.php?currency='.get_currency());}
$s=db()->prepare('SELECT c.quantity,p.*,(SELECT image_path FROM product_images WHERE product_id=p.id LIMIT 1) img FROM cart c JOIN products p ON p.id=c.product_id WHERE c.user_id=?');$s->execute([$_SESSION['user_id']]);$items=$s->fetchAll();$total=0;$cur=get_currency();page_header(t('Sepetim','My Cart')); ?>
<h1 class="page-title">🛒 <?=t('Sepetim','My Cart')?></h1>
<div class="card spacious cart-premium"><div class="cart-head"><div><h2><?=t('Ödeme para birimini sepetten seç','Choose payment currency in your cart')?></h2><p class="muted"><?=t('Tutar seçtiğin para birimiyle hesaplanır ve satın alma sayfasına aynı şekilde gider.','The amount is calculated in your selected currency and continues to checkout that way.')?></p></div><form method="get" class="currency-box"><label><?=t('Para birimi','Currency')?></label><select name="currency" onchange="this.form.submit()"><option value="TRY" <?=$cur==='TRY'?'selected':''?>>TL</option><option value="USD" <?=$cur==='USD'?'selected':''?>>USD / Dolar</option><option value="EUR" <?=$cur==='EUR'?'selected':''?>>EUR / Euro</option></select></form></div></div>
<form method="post" class="card"><table class="table"><tr><th><?=t('Ürün','Product')?></th><th><?=t('Fiyat','Price')?></th><th><?=t('Adet','Qty')?></th><th><?=t('Toplam','Total')?></th><th></th></tr><?php foreach($items as $it): $line=$it['price']*$it['quantity'];$total+=$line;?><tr><td><img src="<?=UPLOAD_URL.'/'.h($it['img']?:'logo.jpg')?>" style="width:60px;height:60px;object-fit:cover;border-radius:12px"> <?=h($it['name'])?></td><td><?=money($it['price'])?></td><td><input type="number" name="qty[<?=$it['id']?>]" min="1" max="<?=$it['stock']?>" value="<?=$it['quantity']?>"></td><td><?=money($line)?></td><td><a class="btn danger" href="?remove=<?=$it['id']?>">Sil</a></td></tr><?php endforeach; ?></table><h2><?=t('Sepet Toplamı','Cart Total')?>: <?=money($total)?></h2><div class="actions"><button class="btn"><?=t('Sepeti Güncelle','Update Cart')?></button><?php if($items): ?><a class="btn primary" href="checkout.php?currency=<?=h($cur)?>"><?=t('Satın Al','Checkout')?></a><?php endif; ?></div></form>
<?php page_footer(); ?>
